// This file is generated by AI.

// 参考音频选择对话框 (从已有参考音频里挑一条, 带搜索)。
//
// 用于语句操作台的「更换…」与配音记录的应用。**添加**参考音频走 `AddReferenceDialog`
// (那里只输入这一条的信息), 列表本身在「编辑角色」对话框里。

import { Button, Input } from '@fluentui/react-components';
import { AddRegular, ArrowDownloadRegular, DeleteRegular } from '@fluentui/react-icons';
import { open as openDialog, save as saveDialog } from '@tauri-apps/plugin-dialog';
import { useEffect, useMemo, useState } from 'react';

import { voiceAddReference, voiceExportCharacter, voiceRemoveReference } from '../commands/voice';
import type { Character, ReferenceAudio } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { useAppStore } from '../state/store';
import { AudioButton } from './AudioButton';
import { voiceController } from './controller';
import { ReferenceTrimDialog } from './ReferenceTrimDialog';
import { LANGUAGE_LABELS } from './types';

interface Props {
  open: boolean;
  character: Character | null;
  selectedHash: string | null;
  onPick: (hash: string) => void;
  onClose: () => void;
  onCharactersChanged: () => void;
}

export function VoiceReferenceDialog({ open, character, selectedHash, onPick, onClose, onCharactersChanged }: Props) {
  const [query, setQuery] = useState('');
  const [trimSource, setTrimSource] = useState<{ path: string; suggestedStart: number; suggestedEnd: number } | null>(
    null
  );
  const [pendingText, setPendingText] = useState('');
  const [language, setLanguage] = useState('zh');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      setError(null);
      setQuery('');
    }
  }, [open]);

  const references = useMemo(() => {
    const list = character?.references ?? [];
    if (!query.trim()) return list;
    const needle = query.trim().toLowerCase();
    return list.filter(
      (reference) =>
        reference.text.toLowerCase().includes(needle) ||
        reference.tags.some((tag) => tag.toLowerCase().includes(needle))
    );
  }, [character, query]);

  if (!open || !character) return null;

  /** 选择本地音频文件并进入添加流程 */
  const pickFile = async () => {
    setError(null);
    const selected = await openDialog({
      multiple: false,
      filters: [{ name: '音频', extensions: ['wav'] }],
    });
    if (typeof selected !== 'string') return;
    setBusy(true);
    try {
      const info = await voiceController.inspectAudio(selected);
      if (info.tooLong) {
        // 过长: 交给裁剪对话框 (展示波形 + 自动建议区间)
        const suggestion = await voiceController.trimSuggestion(selected);
        setTrimSource({
          path: selected,
          suggestedStart: suggestion.suggested.start,
          suggestedEnd: suggestion.suggested.end,
        });
      } else {
        // 过短: 静默补尾 (由后端在规范化时完成)
        setTrimSource({ path: selected, suggestedStart: 0, suggestedEnd: -1 });
      }
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const finishAdd = async (path: string, start?: number, end?: number) => {
    setBusy(true);
    setError(null);
    try {
      const updated = await voiceAddReference(character.id, {
        source: path,
        text: pendingText.trim(),
        language,
        tags: [],
        start,
        end,
      });
      setTrimSource(null);
      setPendingText('');
      voiceController.setCharacters(
        useAppStore.getState().voiceCharacters.map((item) => (item.id === updated.id ? updated : item))
      );
      onCharactersChanged();
      const added = updated.references[updated.references.length - 1];
      if (added) onPick(added.hash);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const removeReference = async (reference: ReferenceAudio) => {
    setBusy(true);
    try {
      const updated = await voiceRemoveReference(character.id, reference.hash);
      voiceController.setCharacters(
        useAppStore.getState().voiceCharacters.map((item) => (item.id === updated.id ? updated : item))
      );
      onCharactersChanged();
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <AppDialog
        title={`参考音频 · ${character.name}`}
        description="参考文本必须与音频逐字一致；时长须在 3~10 秒之间。"
        size="large"
        height={600}
        compact
        onClose={onClose}
        footerLeading={
          <Button
            appearance="secondary"
            icon={<ArrowDownloadRegular />}
            onClick={() => void exportCharacter(character)}
          >
            导出角色
          </Button>
        }
        footer={
          <Button appearance="secondary" onClick={onClose}>
            关闭
          </Button>
        }
      >
        <div className="dialog-toolbar">
          <Input
            className="dialog-toolbar-grow"
            placeholder="搜索参考文本或标签…"
            value={query}
            onChange={(_, data) => setQuery(data.value)}
          />
          <Button appearance="primary" icon={<AddRegular />} disabled={busy} onClick={() => void pickFile()}>
            添加参考音频
          </Button>
        </div>

        <div className="reference-list dialog-scroll">
          {references.length === 0 && <p className="voice-dialog-empty">该角色还没有参考音频。</p>}
          {references.map((reference) => (
            <div key={reference.hash} className={`reference-item${reference.hash === selectedHash ? ' selected' : ''}`}>
              <div className="reference-main" onClick={() => onPick(reference.hash)}>
                <div className="reference-text">{reference.text || '（未填写参考文本）'}</div>
                <div className="reference-meta">
                  {LANGUAGE_LABELS[reference.language] ?? reference.language} · {reference.duration.toFixed(2)}s ·{' '}
                  {Math.round(reference.sampleRate / 1000)}kHz
                  {reference.tags.length > 0 && ` · ${reference.tags.join(' / ')}`}
                </div>
              </div>
              <AudioButton path={voiceController.referencePathFor(character.id, reference.file)} />
              <Button
                size="small"
                appearance="subtle"
                icon={<DeleteRegular />}
                title="删除该参考音频"
                onClick={() => void removeReference(reference)}
              />
            </div>
          ))}
        </div>

        <div className="voice-dialog-section">
          <span className="voice-label">
            参考文本（必填，须与音频逐字一致）
            <span className="voice-required">*</span>
          </span>
          <Input
            value={pendingText}
            placeholder="添加音频时填写的参考文本"
            onChange={(_, data) => setPendingText(data.value)}
          />
        </div>

        {error && <p className="voice-error">{error}</p>}
      </AppDialog>

      {trimSource && (
        <ReferenceTrimDialog
          path={trimSource.path}
          suggestedStart={trimSource.suggestedStart}
          suggestedEnd={trimSource.suggestedEnd}
          requireText={pendingText.trim().length === 0}
          onTextChange={setPendingText}
          text={pendingText}
          language={language}
          onLanguageChange={setLanguage}
          busy={busy}
          error={error}
          onCancel={() => {
            setTrimSource(null);
            setError(null);
          }}
          onConfirm={(start, end) =>
            void finishAdd(trimSource.path, end >= 0 ? start : undefined, end >= 0 ? end : undefined)
          }
        />
      )}
    </>
  );
}

/** 试听按钮: 见共享组件 `AudioButton` */
export { AudioButton } from './AudioButton';

async function exportCharacter(character: Character): Promise<void> {
  const destination = await saveDialog({
    defaultPath: `${character.name}.zip`,
    filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
  });
  if (typeof destination !== 'string') return;
  await voiceExportCharacter(character.id, destination);
}
